PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <https://example.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?zname ?s ?sname WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?zname }
  OPTIONAL { ?z brick:hasSubComponent ?s ; ?p ?s }
  OPTIONAL { ?s rdfs:label ?sname }
}

SELECT ?zone ?label ?sensor WHERE {
  ?zone a <http://brickschema.org/schema/Brick#Zone> .
  OPTIONAL { ?zone <http://www.w3.org/2000/01/rdf-schema#label> ?label }
  OPTIONAL {
    ?zone <http://brickschema.org/schema/Brick#hasPoint> ?sensor .
    ?sensor a <http://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> .
  }
}
ORDER BY ?zone ?label

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?label ?point ?ptype ?tsid WHERE {
  ?zone a <https://brickschema.org/schema/Brick#HVAC_Zone> .
  ?zone <http://www.w3.org/2000/01/rdf-schema#label> ?label .
  ?zone <http://brickschema.org/schema/Brick#hasPoint> ?point .
  ?point ref:hasExternalReference ?r .
  ?r a ref:TimeseriesReference .
  ?r ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point a ?ptype }
} ORDER BY ?label ?point LIMIT 200

